import os,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in __import__('re').finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def squeeze_rows(g):
    out=[]
    for r in g:
        if not out or out[-1]!=r: out.append(r)
    return out
def squeeze_cols(g):
    return [list(c) for c in zip(*squeeze_rows([list(r) for r in zip(*g)]))]
def f(g): return squeeze_cols(squeeze_rows(g))
d=G['Demo pair 1 input']; o=G['Demo pair 1 output']
print(f(d)==o, f(d))
print(json.dumps(f(G['Test input'])))

